\draw[task curve] (0,.5)--(4,.5);\foreach \x/\s in {0/A,4/B}{\draw[task curve,fill=white] (\x,.5) circle (.15);\node[above] at (\x,.7) {$\s$};}\node[left] at (-.1,.5) {$m_1$};\node[right] at (4.1,.5) {$m_2$};\foreach \x/\s in {.8/C,3.2/D}{\draw[task curve] (\x,.5)--++(-.2,-.5)--++(.4,0)--cycle;\node[below] at (\x,0) {$\s$};}\draw[task axis,<->] (0,1.2)--(4,1.2) node[midway,above] {$L$};
